def extract(dest="."):
    raw = base64.b64decode("".join(DATA.split()))
    with zipfile.ZipFile(io.BytesIO(raw)) as z:
        z.extractall(dest)
    print("Unpacked", len(z.namelist()), "files into", os.path.abspath(dest))

if __name__ == "__main__":
    extract(sys.argv[1] if len(sys.argv) > 1 else ".")
